enum class WyrmThemeGroup { THREE, MADE, TWO }

enum class WyrmThemeMode {
    LIGHT, DARK, AUTO;

    val stored: String get() = name.lowercase()

    companion object {
        fun fromStored(value: String?): WyrmThemeMode? = when (value?.trim()?.lowercase()) {
            "light" -> LIGHT
            "dark" -> DARK
            "auto" -> AUTO
            else -> null
        }
    }
}

