        pal(true, 0xFF2F3F34, 0xFF3B4B40, 0xFFF1F5ED, 0xFF2F3F34, 0xFFA0A99F, 0xFFBAC1B9, 0x24F1F5ED, 0x1CF1F5ED, 0xFF3D7B56, 0xFF6C9B7F, 0xFF909A91, 0xF02F3F34, 0xFF657268, 0xFFE17B72, 0xFF576559, 0xFF5F6C60, 0xFF35453A, 0xFF3B4B40, 0xFFF1F5ED, 0xFFA0A99F, 0xFFBAC1B9, 0x24F1F5ED, 0xFF576559, 0xFF3B4B40, 0xFF3B4B40, 0xFF3B4B40, 0xFFF1F5ED, 0xFFA0A99F, 0xFFBAC1B9, 0x24F1F5ED, 0xFF576559, 0xFF3B4B40, 0xFF3B4B40),
