        intArrayOf(0xFF101820.toInt(), 0xFFEAF1F4.toInt(), 0xFF6DB68F.toInt()),
        pal(false, 0xFFEAF1F4, 0xFFF7F9FB, 0xFF101820, 0xFFF7F9FB, 0xFF686E74, 0xFF515960, 0x14101820, 0x12101820, 0xFF69AF89, 0xFF538A6D, 0xFF788084, 0xF0EAF1F4, 0xFFADB4B9, 0xFFC4554D, 0xFFDBE2E5, 0xFFD3DADD, 0xFFF1F5F8, 0xFFF7F9FB, 0xFF101820, 0xFF686E74, 0xFF515960, 0x14101820, 0xFFDBE2E5, 0xFFF7F9FB, 0xFFF7F9FB, 0xFFF7F9FB, 0xFF101820, 0xFF686E74, 0xFF515960, 0x14101820, 0xFFDBE2E5, 0xFFF7F9FB, 0xFFF7F9FB),
        pal(true, 0xFF101820, 0xFF19242D, 0xFFEAF1F4, 0xFF101820, 0xFFAAB8C0, 0xFFC5D0D5, 0x24EAF1F4, 0x1CEAF1F4, 0xFF6DB68F, 0xFF83B8E8, 0xFF9DABB3, 0xF0141E27, 0xFF6B7B85, 0xFFE07972, 0xFF22303A, 0xFF283741, 0xFF1E2A34, 0xFF19242D, 0xFFEAF1F4, 0xFFAAB8C0, 0xFFC5D0D5, 0x24EAF1F4, 0xFF22303A, 0xFF19242D, 0xFF19242D, 0xFF19242D, 0xFFEAF1F4, 0xFFAAB8C0, 0xFFC5D0D5, 0x24EAF1F4, 0xFF22303A, 0xFF19242D, 0xFF19242D),
    );

    /** The side this theme ships on. Callers that know the mode use [side]. */
    val palette: WyrmPalette get() = if (defaultMode == WyrmThemeMode.DARK) dark else light

    fun side(mode: WyrmThemeMode, systemDark: Boolean): WyrmPalette = when (mode) {
        WyrmThemeMode.LIGHT -> light
        WyrmThemeMode.DARK -> dark
        WyrmThemeMode.AUTO -> if (systemDark) dark else light
    }

    companion object {
        fun resolve(name: String?, modeRaw: String?): WyrmThemeChoice {
            val stored = name?.trim()?.lowercase().orEmpty()
            val mode = WyrmThemeMode.fromStored(modeRaw)
            val key = if (stored in setOf("paper", "graphite", "blush", "sun", "slate", "lilac", "forest") || (stored == "midnight" && mode == null)) "classic_" + stored else stored
            if (mode != null) {
                val theme = entries.firstOrNull { it.storedName == key } ?: SAND
                return WyrmThemeChoice(theme, mode)
            }
            return when (key) {
                "paper" -> WyrmThemeChoice(SAND, WyrmThemeMode.LIGHT)
                "graphite" -> WyrmThemeChoice(SAND, WyrmThemeMode.DARK)
                "blush" -> WyrmThemeChoice(LINEN, WyrmThemeMode.LIGHT)
                "sun" -> WyrmThemeChoice(TANGERINE, WyrmThemeMode.LIGHT)
                "slate" -> WyrmThemeChoice(CYAN, WyrmThemeMode.LIGHT)
                "lilac" -> WyrmThemeChoice(GRAPE, WyrmThemeMode.LIGHT)
                "forest" -> WyrmThemeChoice(COLONIAL3, WyrmThemeMode.LIGHT)
                "midnight" -> WyrmThemeChoice(MIDNIGHT, WyrmThemeMode.DARK)
                "" -> WyrmThemeChoice(CLASSIC_PAPER, WyrmThemeMode.LIGHT)
                else -> entries.firstOrNull { it.storedName == key }?.let { WyrmThemeChoice(it, it.defaultMode) }
                    ?: WyrmThemeChoice(SAND, SAND.defaultMode)
            }
        }

        fun fromStored(value: String?): WyrmThemeId = resolve(value, null).theme
    }
}

private fun pal(dark: Boolean, vararg xs: Long): WyrmPalette {
    fun c(i: Int) = Color(xs[i].toInt())
    fun hero(at: Int) = WyrmHero(c(at), c(at + 1), c(at + 2), c(at + 3), c(at + 4), c(at + 5), c(at + 6), c(at + 7))
    return WyrmPalette(
        paper = c(0), card = c(1), ink = c(2), onInk = c(3),
        quiet = c(4), mute = c(5), rule = c(6), rowRule = c(7),
        live = c(8), link = c(9), tabIdle = c(10), tabBar = c(11),
        chevron = c(12), badge = c(13), well = c(14), track = c(15), hover = c(16),
        dark = dark,
        hero = hero(17),
        hero2 = hero(25),
    )
}
